const C = 69.1
class Component extends DCLogic {
  state = { shown: {} }
  componentDidMount() {
    this.arm()
  }
  componentDidUpdate() {
    this.arm()
  }
  arm() {
    const fresh = (this.props.toasts ?? []).filter((t) => !(t.id in this.state.shown))
    if (!fresh.length) return
    requestAnimationFrame(() =>
      requestAnimationFrame(() =>
        this.setState((s) => ({ shown: { ...s.shown, ...Object.fromEntries(fresh.map((t) => [t.id, true])) } })),
      ),
    )
  }
  renderVals() {
    const standalone = this.props.toasts === undefined
    const inline = standalone || !!this.props.inline,
      S = this.state
    return {
      pos: inline ? 'static' : 'fixed',
      pad: standalone ? '20px' : '0',
      items: (standalone ? PREVIEW : this.props.toasts).map((t) => {
        const [color, tile, shadow] = V[t.type] ?? V.info,
          on = inline || S.shown[t.id],
          leaving = t.leaving
        const ms = t.duration ?? 4200,
          sticky = t.type === 'error'
        return {
          ...t,
          color,
          tile,
          shadow,
          isSuccess: t.type === 'success',
          isError: t.type === 'error',
          isWarning: t.type === 'warning',
          isInfo: (t.type ?? 'info') === 'info',
          hasDesc: !!t.desc,
          hasAction: !!t.action,
          op: on && !leaving ? 1 : 0,
          tf: on && !leaving ? 'translateY(0) scale(1)' : 'translateY(12px) scale(.96)',
          off: inline ? (C * 0.38).toFixed(1) : on ? C : 0,
          dur: inline ? '0s' : ms + 'ms',
          ringOp: sticky ? 0 : 1,
          close: () => this.props.onDismiss?.(t.id),
          act: () => {
            t.onAction?.()
            this.props.onDismiss?.(t.id)
          },
        }
      }),
    }
  }
}

